tool_and_message_events.command:
/bin/bash -lc 'set -e
case_dir=$(mktemp -d "$PWD/.release-review.XXXXXX")
trap '"'find \""'$case_dir" -depth -delete'"' EXIT
cp -R release/. \""'$case_dir/"
cp vendor/hono-4.13.19.tgz "$case_dir/"
cd "$case_dir"
export npm_config_cache="$case_dir/.npm-cache"
export npm_config_userconfig="$case_dir/.npmrc-user"
export npm_config_globalconfig="$case_dir/.npmrc-global"
npm install --offline --ignore-scripts --no-audit --no-fund ./hono-4.13.19.tgz
node -p '"'require(\"./node_modules/hono/package.json\").version'
npm test
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import app from './app.mjs';

const scenarios = [
  { name: 'valid record', id: 'a7', session: true, status: 200, body: { id: 'a7', title: 'Harbor' }, steps: 'dispatch,session,read' },
  { name: 'no session', id: 'a7', session: false, status: 401, body: { error: 'sign_in' }, steps: 'dispatch,session' },
  { name: 'missing record', id: 'missing', session: true, status: 404, body: { error: 'not_found' }, steps: 'dispatch,session,read' },
  { name: 'invalid record', id: 'b4', session: true, status: 502, body: { error: 'invalid_record' }, steps: 'dispatch,session,read,error' },
  { name: 'invalid record without session', id: 'b4', session: false, status: 401, body: { error: 'sign_in' }, steps: 'dispatch,session' },
];
let failed = false;
for (const testCase of scenarios) {
  try {
    const request = new Request('http://localhost/desk/' + testCase.id, {
      method: 'GET',
      headers: testCase.session ? { 'x-shift': 'day' } : {},
    });
    const response = await app.request(request);
    assert.ok(response instanceof Response);
    const observed = {
      status: response.status,
      contentType: response.headers.get('content-type'),
      steps: response.headers.get('x-desk-steps'),
      body: await response.json(),
    };
    console.log(testCase.name, JSON.stringify(observed));
    assert.deepEqual(observed, {
      status: testCase.status,
      contentType: 'application/json',
      steps: testCase.steps,
      body: testCase.body,
    });
  } catch (error) {
    failed = true;
    console.error(testCase.name, error);
  }
}
process.exitCode = Number(failed);
NODE"

